/// Builds the Swift source of the generated `Secrets.swift` file.
///
/// The file is a `Secrets` enum with one throwing property per secret, plus the error type and
/// `decrypt(_:_:)` function those properties use, and a `#Playground` block to check them.
///
/// - Important: The generated file is meant to be committed to source control, so nothing here may
///   ever include a secret's plaintext value, not even in a comment.
enum GeneratedSource {
    /// The complete `Secrets.swift` file.
    /// - Parameters:
    ///   - properties: The source of each secret's property, from ``property(for:encrypted:)``.
    ///   - propertyNames: The name of each property, in the same order, for the `#Playground` block.
    /// - Returns: The Swift source, without a trailing newline.
    static func file(properties: [String], propertyNames: [String]) -> String {
        let playgroundChecks = propertyNames.enumerated().map { offset, name in
            "let check\(offset + 1) = try Secrets.\(name)\n"
        }.joined()

        return """
        \(header)
        enum Secrets {
        \(errorType)

        \(properties.joined(separator: "\n\n"))

        \(decryptFunction)
        }

        #Playground("Check API Coding") {
        \(playgroundChecks)
        }
        """
    }

    /// The source of the throwing `Secrets` property that decrypts one secret.
    /// - Parameters:
    ///   - secret: The secret, whose ``NamedSecret/name`` becomes the property name. Its value is
    ///     never written.
    ///   - encrypted: The secret's encrypted content and key, written as byte arrays.
    /// - Returns: The property's source, indented to sit inside `enum Secrets`.
    static func property(for secret: NamedSecret, encrypted: Obfuscate.Encrypted) -> String {
        let contentBytes = encrypted.content.map(\.hexLiteral).joined(separator: ", ")
        let keyBytes = encrypted.key.map(\.hexLiteral).joined(separator: ", ")

        let docComment = if secret.hasGeneratedName {
            """
                /// Obfuscated secret.
                ///
                /// Rename `\(secret.name)` (here and in the `#Playground` below) to describe what it's for.
            """
        } else {
            "    /// Obfuscated secret `\(secret.name)`."
        }

        return """
        \(docComment)
            ///
            /// - Throws: ``ObfuscateError`` if the secret can't be decrypted.
            static var \(secret.name): String {
                get throws {
                    let a: [UInt8] = [
                        \(contentBytes)
                    ]

                    let b: [UInt8] = [
                        \(keyBytes)
                    ]

                    return try decrypt(a, b)
                }
            }
        """
    }

    /// The imports and the documentation comment for `enum Secrets`.
    private static let header = """
        import Foundation
        import CryptoKit
        import Playgrounds

        // Secrets.swift

        /// `Secrets` lets us obfuscate secrets, such as API keys, without committing the actual keys \
        to source control
        ///
        /// This enum was generated by the in-house CLI tool `obfuscate`, and should not be altered. \
        See `obfuscate -h` for more info on the tool
        ///
        /// Reading a secret can throw, although it never should unless this file has been edited:
        ///
        /// ```swift
        /// let apiKey = try Secrets.apiKey1
        /// ```
        ///
        /// - Note: This method of obfuscating secrets was based on a blog post at \
        [NSHipster](https://nshipster.com/secrets/)
        ///
        /// - Important: This is **not** high-tech encryption. It's merely obfuscation. \
        If *anyone* wants to crack this, it's trivially easy to do so. \
        It just means they have to be motivated enough to do *some* work, rather than have the keys in plain sight.
        """

    /// The `Secrets.ObfuscateError` type thrown by the generated properties, indented to sit inside `enum Secrets`.
    private static let errorType = """
            /// Thrown when a secret can't be decrypted.
            ///
            /// This should never happen unless this file has been edited or corrupted.
            enum ObfuscateError: Error, LocalizedError {
                /// CryptoKit couldn't decrypt the secret.
                case decryptionFailed(underlying: any Error)

                /// The secret decrypted, but the result isn't valid UTF-8 text.
                case invalidUTF8

                /// What went wrong.
                var errorDescription: String? {
                    switch self {
                    case .decryptionFailed:
                        "Couldn't decrypt a secret."
                    case .invalidUTF8:
                        "A decrypted secret isn't valid UTF-8 text."
                    }
                }

                /// Why it went wrong.
                var failureReason: String? {
                    switch self {
                    case .decryptionFailed(let underlying):
                        "CryptoKit reported: \\(underlying.localizedDescription)"
                    case .invalidUTF8:
                        "The decrypted bytes don't form a valid UTF-8 string."
                    }
                }

                /// What the developer can do about it.
                var recoverySuggestion: String? {
                    "Secrets.swift has probably been edited or corrupted. Regenerate it with the obfuscate tool."
                }

                /// No Help Book anchor: this error is for developers, not end users.
                var helpAnchor: String? {
                    nil
                }
            }
        """

    /// The `Secrets.decrypt(_:_:)` function used by the generated properties, indented to sit inside
    /// `enum Secrets`.
    private static let decryptFunction = """
            /// Decrypts some bytes and returns the clear text.
            /// - Parameters:
            ///   - content: The encrypted content to be decrypted
            ///   - key: The key to use to decrypt it
            /// - Returns: The decrypted string
            /// - Throws: ``ObfuscateError`` if the content can't be decrypted.
            static func decrypt(_ content: [UInt8], _ key: [UInt8]) throws -> String {
                let decrypted: Data
                do {
                    let sealedBox = try ChaChaPoly.SealedBox(combined: Data(content))
                    decrypted = try ChaChaPoly.open(sealedBox, using: SymmetricKey(data: Data(key)))
                } catch {
                    throw ObfuscateError.decryptionFailed(underlying: error)
                }

                guard let secret = String(bytes: decrypted, encoding: .utf8) else {
                    throw ObfuscateError.invalidUTF8
                }
                return secret
            }
        """
}
